def query_index_get(
    query: str = QueryParam(..., description="Search query string"),
    repo_id: Optional[str] = QueryParam(None, description="Optional repo_id restrict filter"),
    top_k: int = QueryParam(5, ge=1, le=50, description="Top K results")
):
