                    chunks_stored += 1

            return {
                "status": "success",
                "repo_id": req.repo_id,
                "files_processed": len(code_files),
                "chunks_stored": chunks_stored,
                "chunks_indexed": chunks_stored,
            }
        finally:
            github_tools.cleanup_repo(repo_path)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


